-- ===========================================================================
-- 030_lesson_quizzes.sql
-- Program catalog reseed:
--   * one quiz per lesson (unique quiz id + question ids) so a trainee's
--     attempt on one lesson can never show up on another lesson; and
--   * the course emoji field is dropped (courses now use Lucide icons).
-- Safe to re-run (upsert by id).
-- ===========================================================================

insert into public.programs (id, code, title, trainer_id, data)
values ('housekeeping', 'HK-102', 'Housekeeping NC II', 'tr-001', $prog${"id":"housekeeping","code":"HK-102","title":"Housekeeping NC II","category":"Tourism & Hospitality","level":"NC II","special":false,"enrollable":false,"description":"Prepare trainees to clean and prepare guest rooms, handle linen, and deliver quality housekeeping services in hotels and resorts.","overview":"The Housekeeping NC II program equips trainees with the skills to maintain cleanliness and orderliness in guest rooms and public areas of hospitality establishments. It covers room cleaning, bed making, bathroom sanitation, linen management and guest room inspection.","duration":"3 months","hours":160,"fee":8500,"color":"from-sky-500 to-blue-600","image":"/courses/housekeeping.jpg","requirements":["At least 18 years old","High School graduate or ALS equivalent","Physically fit (medical certificate)","Birth certificate (PSA)","2 pcs. 2x2 ID picture","Barangay clearance"],"trainerId":"tr-001","competencies":[{"id":"housekeeping-basic","type":"Basic","title":"Basic Competency","description":"Foundational skills required of every trainee: communication, numeracy, digital literacy and workplace behavior.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"housekeeping-basic-l1","title":"Reading, Writing & Comprehension","description":"Develop the ability to read, interpret and write workplace documents, forms and simple reports.","duration":45,"video":"Introduction to Workplace Literacy","materials":[{"id":"housekeeping-basic-l1-m1","name":"Reading Comprehension Guide.pdf","type":"pdf","url":""},{"id":"housekeeping-basic-l1-m2","name":"Workplace Forms Template.docx","type":"doc","url":""}],"content":"This lesson builds the foundational literacy skills needed in a technical-vocational workplace. You will practice reading instructions, interpreting forms, and writing simple reports and messages clearly and accurately.","quizId":"housekeeping-basic-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"housekeeping-basic-l2","title":"Basic Communication Skills","description":"Learn verbal and non-verbal communication techniques for professional workplace interaction.","duration":40,"video":"Effective Workplace Communication","materials":[{"id":"housekeeping-basic-l2-m1","name":"Communication Etiquette Handout.pdf","type":"pdf","url":""}],"content":"Communication is the backbone of any workplace. This lesson covers active listening, professional tone, giving and receiving feedback, and adapting your communication style to different audiences.","quizId":"housekeeping-basic-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"housekeeping-basic-l3","title":"Basic Digital Literacy","description":"Familiarize yourself with computers, the internet, email and basic productivity tools.","duration":60,"video":"Getting Started with Computers","materials":[{"id":"housekeeping-basic-l3-m1","name":"Digital Skills Workbook.pdf","type":"pdf","url":""},{"id":"housekeeping-basic-l3-m2","name":"Keyboard Shortcuts Cheatsheet.pdf","type":"pdf","url":""}],"content":"Digital literacy is essential for modern employment. This lesson introduces operating systems, file management, internet browsing, email, and cloud-based productivity tools.","quizId":"housekeeping-basic-l3-quiz"},{"videoUrl":"","published":true,"order":4,"id":"housekeeping-basic-l4","title":"Workplace Behavior & Professionalism","description":"Understand workplace ethics, punctuality, grooming, and professional conduct.","duration":35,"video":"Professional Conduct at Work","materials":[{"id":"housekeeping-basic-l4-m1","name":"Code of Conduct.pdf","type":"pdf","url":""}],"content":"Professionalism covers punctuality, appropriate attire, respect for colleagues, following rules and regulations, and taking responsibility for your work.","quizId":"housekeeping-basic-l4-quiz"}]},{"id":"housekeeping-common","type":"Common","title":"Common Competency","description":"Skills common across technical-vocational industries: workplace communication, safety, customer service and teamwork.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"housekeeping-common-l1","title":"Workplace Communication","description":"Communicate effectively with clients, colleagues and supervisors using industry-appropriate language.","duration":50,"video":"Communicating in the Workplace","materials":[{"id":"housekeeping-common-l1-m1","name":"Communication Scenarios.pdf","type":"pdf","url":""}],"content":"This lesson focuses on industry-specific communication: handling inquiries, reporting incidents, participating in meetings, and documenting work activities.","quizId":"housekeeping-common-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"housekeeping-common-l2","title":"Workplace Safety & Emergency Procedures","description":"Identify hazards, follow OSH standards, and respond to workplace emergencies.","duration":55,"video":"Occupational Safety and Health","materials":[{"id":"housekeeping-common-l2-m1","name":"OSH Standards Manual.pdf","type":"pdf","url":""},{"id":"housekeeping-common-l2-m2","name":"Emergency Evacuation Plan.pdf","type":"pdf","url":""}],"content":"Occupational Safety and Health (OSH) is a legal requirement. Learn to identify hazards, use protective equipment, follow safety signage, and respond to emergencies such as fire, earthquake, and medical incidents.","quizId":"housekeeping-common-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"housekeeping-common-l3","title":"Customer Service Excellence","description":"Deliver quality service that meets and exceeds customer expectations.","duration":45,"video":"Service Quality Standards","materials":[{"id":"housekeeping-common-l3-m1","name":"Customer Service Standards.pdf","type":"pdf","url":""}],"content":"Excellent customer service builds loyalty and reputation. Learn the principles of service quality, handling complaints, and creating positive customer experiences.","quizId":"housekeeping-common-l3-quiz"},{"videoUrl":"","published":true,"order":4,"id":"housekeeping-common-l4","title":"Working with Others & Time Management","description":"Collaborate effectively in teams and manage your time and priorities.","duration":40,"video":"Teamwork and Productivity","materials":[{"id":"housekeeping-common-l4-m1","name":"Teamwork Activity Sheet.pdf","type":"pdf","url":""}],"content":"Success in the workplace depends on teamwork and personal productivity. This lesson covers collaboration, conflict resolution, prioritization, and effective scheduling.","quizId":"housekeeping-common-l4-quiz"}]},{"id":"housekeeping-core","type":"Core","title":"Core Competency","description":"The core competencies of Housekeeping NC II: preparing guest rooms, cleaning procedures, bed making, bathroom cleaning, and guest room inspection.","lessons":[],"units":[{"id":"housekeeping-core-u1","title":"Room Cleaning Procedures","description":"Clean and prepare guest rooms according to establishment standards.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"housekeeping-core-u1-l1","title":"Introduction to Housekeeping Operations","description":"Understand the role of housekeeping in the hospitality industry.","duration":45,"video":"Introduction to Housekeeping Operations","materials":[{"id":"housekeeping-core-u1-l1-m1","name":"Housekeeping Dept. Overview.pdf","type":"pdf","url":""}],"content":"Housekeeping is the heart of hospitality. This lesson introduces the department structure, roles and responsibilities, grooming standards, and the importance of cleanliness to guest satisfaction.","quizId":"housekeeping-core-u1-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"housekeeping-core-u1-l2","title":"Cleaning Equipment & Chemicals","description":"Identify, use and maintain cleaning tools, equipment and chemicals safely.","duration":50,"video":"Cleaning Equipment & Chemicals","materials":[{"id":"housekeeping-core-u1-l2-m1","name":"Cleaning Equipment Catalogue.pdf","type":"pdf","url":""},{"id":"housekeeping-core-u1-l2-m2","name":"Chemical Safety Data Sheet.pdf","type":"pdf","url":""}],"content":"Learn to identify common cleaning equipment such as vacuum cleaners, mops, and caddies. Understand chemical dilution, safety data sheets, and proper storage.","quizId":"housekeeping-core-u1-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"housekeeping-core-u1-l3","title":"Guest Room Preparation","description":"Systematically clean and prepare a guest room for occupancy.","duration":60,"video":"Guest Room Preparation","materials":[{"id":"housekeeping-core-u1-l3-m1","name":"Room Cleaning Checklist.pdf","type":"pdf","url":""}],"content":"Follow the standard sequence for guest room cleaning: entering the room, dusting, bed making, bathroom cleaning, replenishing supplies, and final inspection.","quizId":"housekeeping-core-u1-l3-quiz"}]},{"id":"housekeeping-core-u2","title":"Bed Making & Linen Handling","description":"Perform professional bed making and manage linen inventory.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"housekeeping-core-u2-l1","title":"Bed Making Techniques","description":"Make beds to hotel standards including bed stripping and triple sheeting.","duration":45,"video":"Bed Making Techniques","materials":[{"id":"housekeeping-core-u2-l1-m1","name":"Bed Making Steps.pdf","type":"pdf","url":""}],"content":"Learn the step-by-step process of stripping, making, and inspecting a bed. Covers fitted sheets, flat sheets, duvets, pillowcases and decorative arrangements.","quizId":"housekeeping-core-u2-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"housekeeping-core-u2-l2","title":"Linen Room Management","description":"Sort, store and control linen inventory and laundering.","duration":40,"video":"Linen Room Management","materials":[{"id":"housekeeping-core-u2-l2-m1","name":"Linen Inventory Sheet.pdf","type":"pdf","url":""}],"content":"Manage linen par levels, sort soiled linen, coordinate with laundry, and maintain linen room organization to avoid losses.","quizId":"housekeeping-core-u2-l2-quiz"}]},{"id":"housekeeping-core-u3","title":"Bathroom Cleaning & Sanitation","description":"Deep-clean and sanitize bathrooms using proper techniques.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"housekeeping-core-u3-l1","title":"Bathroom Cleaning Sequence","description":"Clean and sanitize all bathroom fixtures and surfaces.","duration":50,"video":"Bathroom Cleaning Sequence","materials":[{"id":"housekeeping-core-u3-l1-m1","name":"Bathroom Cleaning Guide.pdf","type":"pdf","url":""}],"content":"Learn top-to-bottom bathroom cleaning: mirrors, sink, toilet, shower/bathtub, floor, and amenities replenishment. Emphasizes hygiene and cross-contamination prevention.","quizId":"housekeeping-core-u3-l1-quiz"}]},{"id":"housekeeping-core-u4","title":"Guest Room Inspection","description":"Inspect rooms and handle guest requests and complaints.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"housekeeping-core-u4-l1","title":"Room Inspection Standards","description":"Apply quality standards during guest room inspection.","duration":45,"video":"Room Inspection Standards","materials":[{"id":"housekeeping-core-u4-l1-m1","name":"Inspection Standards.pdf","type":"pdf","url":""}],"content":"Use inspection checklists to verify cleanliness, functionality, and presentation. Learn how to document and escalate issues.","quizId":"housekeeping-core-u4-l1-quiz"}]}]}],"quizzes":[{"id":"housekeeping-basic-l1-quiz","programId":"housekeeping","title":"Reading, Writing & Comprehension Quiz","passing":75,"timeLimit":10,"published":true,"questions":[{"id":"housekeeping-basic-l1-quiz-q1","type":"mcq","q":"Which chemical is best for disinfecting bathroom surfaces?","options":["Bleach solution","Cooking oil","Shampoo","Fabric softener"],"answer":"Bleach solution"},{"id":"housekeeping-basic-l1-quiz-q2","type":"tf","q":"Cleaning chemicals should always be stored in unlabeled containers.","answer":false},{"id":"housekeeping-basic-l1-quiz-q3","type":"id","q":"The process of removing dirt and germs from surfaces is called ______.","answer":"sanitizing"},{"id":"housekeeping-basic-l1-quiz-q4","type":"mcq","q":"What is the correct order when cleaning a guest room?","options":["Bathroom first, then bedroom","Dust top to bottom","Clean floor first","Make bed last only"],"answer":"Dust top to bottom"},{"id":"housekeeping-basic-l1-quiz-q5","type":"tf","q":"Wet floor signs should be placed after mopping to prevent accidents.","answer":true}],"lessonId":"housekeeping-basic-l1"},{"id":"housekeeping-basic-l2-quiz","programId":"housekeeping","title":"Basic Communication Skills Quiz","passing":75,"timeLimit":10,"published":true,"questions":[{"id":"housekeeping-basic-l2-quiz-q1","type":"mcq","q":"How many flat sheets are typically used in triple sheeting?","options":["One","Two","Three","Four"],"answer":"Three"},{"id":"housekeeping-basic-l2-quiz-q2","type":"tf","q":"You should knock and announce yourself before entering an occupied guest room.","answer":true},{"id":"housekeeping-basic-l2-quiz-q3","type":"id","q":"A _____ is used to collect dirty linen and trash from guest rooms.","answer":"caddie"},{"id":"housekeeping-basic-l2-quiz-q4","type":"mcq","q":"Which area should be cleaned first in a bathroom?","options":["Floor","Mirror and sink","Toilet","Shower"],"answer":"Mirror and sink"},{"id":"housekeeping-basic-l2-quiz-q5","type":"tf","q":"A guest room should be inspected before being released for occupancy.","answer":true}],"lessonId":"housekeeping-basic-l2"},{"id":"housekeeping-basic-l3-quiz","programId":"housekeeping","title":"Basic Digital Literacy Quiz","passing":75,"timeLimit":8,"published":true,"questions":[{"id":"housekeeping-basic-l3-quiz-q1","type":"mcq","q":"What is the first step in bed making?","options":["Stripping the bed","Placing the duvet","Fluffing pillows","Vacuuming"],"answer":"Stripping the bed"},{"id":"housekeeping-basic-l3-quiz-q2","type":"tf","q":"Soiled linen should 