on conflict (id) do update set code = excluded.code, title = excluded.title, trainer_id = excluded.trainer_id, data = excluded.data;

insert into public.programs (id, code, title, trainer_id, data)
values ('barista', 'BAR-204', 'Barista NC II', 'tr-002', $prog${"id":"barista","code":"BAR-204","title":"Barista NC II","category":"Tourism & Hospitality","level":"NC II","special":false,"enrollable":false,"description":"Train in coffee preparation, espresso extraction, milk steaming and latte art to become a professional barista.","overview":"The Barista NC II program develops the skills required to prepare and serve a variety of espresso-based and brewed coffee beverages. It covers coffee fundamentals, espresso preparation, milk texturing, latte art, and beverage menu preparation with excellent customer service.","duration":"2 months","hours":120,"fee":7500,"color":"from-amber-500 to-orange-600","image":"/courses/barista.jpg","requirements":["At least 18 years old","High School graduate or ALS equivalent","Physically fit (medical certificate)","Birth certificate (PSA)","2 pcs. 2x2 ID picture","Barangay clearance"],"trainerId":"tr-002","competencies":[{"id":"barista-basic","type":"Basic","title":"Basic Competency","description":"Foundational skills required of every trainee: communication, numeracy, digital literacy and workplace behavior.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"barista-basic-l1","title":"Reading, Writing & Comprehension","description":"Develop the ability to read, interpret and write workplace documents, forms and simple reports.","duration":45,"video":"Introduction to Workplace Literacy","materials":[{"id":"barista-basic-l1-m1","name":"Reading Comprehension Guide.pdf","type":"pdf","url":""},{"id":"barista-basic-l1-m2","name":"Workplace Forms Template.docx","type":"doc","url":""}],"content":"This lesson builds the foundational literacy skills needed in a technical-vocational workplace. You will practice reading instructions, interpreting forms, and writing simple reports and messages clearly and accurately.","quizId":"barista-basic-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"barista-basic-l2","title":"Basic Communication Skills","description":"Learn verbal and non-verbal communication techniques for professional workplace interaction.","duration":40,"video":"Effective Workplace Communication","materials":[{"id":"barista-basic-l2-m1","name":"Communication Etiquette Handout.pdf","type":"pdf","url":""}],"content":"Communication is the backbone of any workplace. This lesson covers active listening, professional tone, giving and receiving feedback, and adapting your communication style to different audiences.","quizId":"barista-basic-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"barista-basic-l3","title":"Basic Digital Literacy","description":"Familiarize yourself with computers, the internet, email and basic productivity tools.","duration":60,"video":"Getting Started with Computers","materials":[{"id":"barista-basic-l3-m1","name":"Digital Skills Workbook.pdf","type":"pdf","url":""},{"id":"barista-basic-l3-m2","name":"Keyboard Shortcuts Cheatsheet.pdf","type":"pdf","url":""}],"content":"Digital literacy is essential for modern employment. This lesson introduces operating systems, file management, internet browsing, email, and cloud-based productivity tools.","quizId":"barista-basic-l3-quiz"},{"videoUrl":"","published":true,"order":4,"id":"barista-basic-l4","title":"Workplace Behavior & Professionalism","description":"Understand workplace ethics, punctuality, grooming, and professional conduct.","duration":35,"video":"Professional Conduct at Work","materials":[{"id":"barista-basic-l4-m1","name":"Code of Conduct.pdf","type":"pdf","url":""}],"content":"Professionalism covers punctuality, appropriate attire, respect for colleagues, following rules and regulations, and taking responsibility for your work.","quizId":"barista-basic-l4-quiz"}]},{"id":"barista-common","type":"Common","title":"Common Competency","description":"Skills common across technical-vocational industries: workplace communication, safety, customer service and teamwork.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"barista-common-l1","title":"Workplace Communication","description":"Communicate effectively with clients, colleagues and supervisors using industry-appropriate language.","duration":50,"video":"Communicating in the Workplace","materials":[{"id":"barista-common-l1-m1","name":"Communication Scenarios.pdf","type":"pdf","url":""}],"content":"This lesson focuses on industry-specific communication: handling inquiries, reporting incidents, participating in meetings, and documenting work activities.","quizId":"barista-common-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"barista-common-l2","title":"Workplace Safety & Emergency Procedures","description":"Identify hazards, follow OSH standards, and respond to workplace emergencies.","duration":55,"video":"Occupational Safety and Health","materials":[{"id":"barista-common-l2-m1","name":"OSH Standards Manual.pdf","type":"pdf","url":""},{"id":"barista-common-l2-m2","name":"Emergency Evacuation Plan.pdf","type":"pdf","url":""}],"content":"Occupational Safety and Health (OSH) is a legal requirement. Learn to identify hazards, use protective equipment, follow safety signage, and respond to emergencies such as fire, earthquake, and medical incidents.","quizId":"barista-common-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"barista-common-l3","title":"Customer Service Excellence","description":"Deliver quality service that meets and exceeds customer expectations.","duration":45,"video":"Service Quality Standards","materials":[{"id":"barista-common-l3-m1","name":"Customer Service Standards.pdf","type":"pdf","url":""}],"content":"Excellent customer service builds loyalty and reputation. Learn the principles of service quality, handling complaints, and creating positive customer experiences.","quizId":"barista-common-l3-quiz"},{"videoUrl":"","published":true,"order":4,"id":"barista-common-l4","title":"Working with Others & Time Management","description":"Collaborate effectively in teams and manage your time and priorities.","duration":40,"video":"Teamwork and Productivity","materials":[{"id":"barista-common-l4-m1","name":"Teamwork Activity Sheet.pdf","type":"pdf","url":""}],"content":"Success in the workplace depends on teamwork and personal productivity. This lesson covers collaboration, conflict resolution, prioritization, and effective scheduling.","quizId":"barista-common-l4-quiz"}]},{"id":"barista-core","type":"Core","title":"Core Competency","description":"Core competencies of Barista NC II: coffee fundamentals, espresso preparation, milk steaming and latte art, and beverage menu preparation.","lessons":[],"units":[{"id":"barista-core-u1","title":"Coffee Fundamentals","description":"Understand coffee varieties, origins, roasting and flavor profiles.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"barista-core-u1-l1","title":"Introduction to Coffee","description":"Explore the history, varieties and journey of coffee from bean to cup.","duration":45,"video":"Introduction to Coffee","materials":[{"id":"barista-core-u1-l1-m1","name":"Coffee Origins Chart.pdf","type":"pdf","url":""}],"content":"Learn about Arabica and Robusta, coffee-growing regions, processing methods, and how origin and roast affect flavor.","quizId":"barista-core-u1-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"barista-core-u1-l2","title":"Coffee Roasting & Grinding","description":"Understand roast levels and proper grinding for different brew methods.","duration":50,"video":"Coffee Roasting & Grinding","materials":[{"id":"barista-core-u1-l2-m1","name":"Grind Size Guide.pdf","type":"pdf","url":""}],"content":"Roast level dramatically affects taste. Learn light, medium and dark roasts, and how grind size must match the brewing method.","quizId":"barista-core-u1-l2-quiz"}]},{"id":"barista-core-u2","title":"Espresso Preparation","description":"Calibrate and extract consistent, high-quality espresso shots.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"barista-core-u2-l1","title":"The Espresso Machine","description":"Operate and maintain the espresso machine and grinder.","duration":55,"video":"The Espresso Machine","materials":[{"id":"barista-core-u2-l1-m1","name":"Espresso Machine Manual.pdf","type":"pdf","url":""}],"content":"Identify machine parts, understand pressure and temperature, and perform daily cleaning and backflushing routines.","quizId":"barista-core-u2-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"barista-core-u2-l2","title":"Dialing In the Shot","description":"Adjust grind and dose to achieve ideal extraction.","duration":50,"video":"Dialing In the Shot","materials":[{"id":"barista-core-u2-l2-m1","name":"Extraction Troubleshooting.pdf","type":"pdf","url":""}],"content":"Learn to diagnose over- and under-extraction, adjust grind, dose and tamp, and taste-test to standardize your espresso.","quizId":"barista-core-u2-l2-quiz"}]},{"id":"barista-core-u3","title":"Milk Steaming & Latte Art","description":"Steam milk to the correct texture and pour latte art.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"barista-core-u3-l1","title":"Milk Texturing","description":"Steam milk to create microfoam for espresso beverages.","duration":45,"video":"Milk Texturing","materials":[{"id":"barista-core-u3-l1-m1","name":"Milk Steaming Steps.pdf","type":"pdf","url":""}],"content":"Learn proper milk steaming technique for different temperatures and textures, including dairy and alternative milks.","quizId":"barista-core-u3-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"barista-core-u3-l2","title":"Basic Latte Art","description":"Pour a heart and rosetta using free-pour technique.","duration":50,"video":"Basic Latte Art","materials":[{"id":"barista-core-u3-l2-m1","name":"Latte Art Reference.pdf","type":"pdf","url":""}],"content":"Master milk-pitcher control to pour hearts, tulips and rosettas. Practice consistency and cup presentation.","quizId":"barista-core-u3-l2-quiz"}]},{"id":"barista-core-u4","title":"Beverage Menu & Customer Service","description":"Prepare the full beverage menu and serve customers.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"barista-core-u4-l1","title":"Building the Beverage Menu","description":"Prepare espresso-based and brewed beverages to recipe.","duration":55,"video":"Building the Beverage Menu","materials":[{"id":"barista-core-u4-l1-m1","name":"Standard Recipes.pdf","type":"pdf","url":""}],"content":"Prepare Americano, cappuccino, latte, flat white, mocha, and manual brews following standard recipes and presentation.","quizId":"barista-core-u4-l1-quiz"}]}]}],"quizzes":[{"id":"barista-basic-l1-quiz","programId":"barista","title":"Reading, Writing & Comprehension Quiz","passing":75,"timeLimit":10,"published":true,"questions":[{"id":"barista-basic-l1-quiz-q1","type":"mcq","q":"Which coffee species is generally considered higher quality?","options":["Arabica","Robusta","Liberica","Excelsa"],"answer":"Arabica"},{"id":"barista-basic-l1-quiz-q2","type":"tf","q":"Finer grind is used for espresso than for French press.","answer":true},{"id":"barista-basic-l1-quiz-q3","type":"id","q":"The process of heating milk with steam to create foam is called ______.","answer":"steaming"},{"id":"barista-basic-l1-quiz-q4","type":"mcq","q":"A darker roast generally produces what flavor?","options":["Smoky and bitter","Fruity and bright","Floral and light","Sour"],"answer":"Smoky and bitter"},{"id":"barista-basic-l1-quiz-q5","type":"tf","q":"Coffee beans should be stored in an airtight container away from light.","answer":true}],"lessonId":"barista-basic-l1"},{"id":"barista-basic-l2-quiz","programId":"barista","title":"Basic Communication Skills Quiz","passing":75,"timeLimit":10,"published":true,"questions":[{"id":"barista-basic-l2-quiz-q1","type":"mcq","q":"A standard single espresso shot is approximately how many ounces?","options":["1 oz","3 oz","5 oz","8 oz"],"answer":"1 oz"},{"id":"barista-basic-l2-quiz-q2","type":"tf","q":"Under-extracted espresso tastes sour and thin.","answer":true},{"id":"barista-basic-l2-quiz-q3","type":"id","q":"The tool used to level and press coffee grounds is called a ______.","answer":"tamper"},{"id":"barista-basic-l2-quiz-q4","type":"mcq","q":"What is the ideal espresso extraction time for a double shot?","options":["20-30 seconds","5 seconds","60 seconds","2 minutes"],"answer":"20-30 seconds"}],"lessonId":"barista-basic-l2"},{"id":"barista-basic-l3-quiz","programId":"barista","title":"Basic Digital Literacy Quiz","passing":75,"timeLimit":8,"published":true,"questions":[{"id":"barista-basic-l3-quiz-q1","type":"mcq","q":"The ideal microfoam texture is best described as:","options":["Glossy wet paint","Dry and stiff","Large bubbles","Watery"],"answer":"Glossy wet paint"},{"id":"barista-basic-l3-quiz-q2","type":"tf","q":"Milk should be steamed to about 60-65°C for best taste.","answer":true},{"id":"barista-basic-l3-quiz-q3","type":"id","q":"The free-pour pattern that looks like a leaf is called a ______.","answer":"rosetta"},{"id":"barista-basic-l3-quiz-q4","type":"mcq","q":"Over-steaming milk results in:","options":["Burnt, flat taste","Sweet flavor","Better foam","Colder milk"],"answer":"Burnt, flat taste"}],"lessonId":"barista-basic-l3"},{"id":"barista-basic-l4-quiz","programId":"barista","title":"Workplace Behavior & Professionalism Quiz","passing":75,"timeLimit":10,"published":true,"questions":[{"id":"barista-basic-l4-quiz-q1","type":"mcq","q":"Which coffee species is generally considered higher quality?","options":["Arabica","Robusta","Liberica","Excelsa"],"answer":"Arabica"},{"id":"barista-basic-l4-quiz-q2","type":"tf","q":"Finer grind is used for espresso than for French press.","answer":true},{"id":"barista-basic-l4-quiz-q3","type":"id","q":"The process of heating milk with steam to create foam is called ______.","answer":"steaming"},{"id":"barista-basic-l4-quiz-q4","type":"mcq","q":"A darker roast generally produces what flavor?","options":["Smoky and bitter","Fruity and bright","Floral and light","Sour"],"answer":"Smoky and bitter"},{"id":"barista-basic-l4-quiz-q5","type":"tf","q":"Coffee beans should be stored in an airtight container away from light.","answer":true}],"lessonId":"barista-basic-l4"},{"id":"barista-common-l1-quiz","programId":"barista","title":"Workplace Communication Quiz","passing":75,"timeLimit":10,"published":true,"questions":[{"id":"barista-common-l1-quiz-q1","type":"mcq","q":"A standard single espresso shot is approximately how many ounces?","options":["1 oz","3 oz","5 oz","8 oz"],"answer":"1 oz"},{"id":"barista-common-l1-quiz-q2","type":"tf","q":"Under-extracted espresso tastes sour and thin.","answer":true},{"id":"barista-common-l1-quiz-q3","type":"id","q":"The tool used to level and press coffee grounds is called a ______.","answer":"tamper"},{"id":"barista-common-l1-quiz-q4","type":"mcq","q":"What is the ideal espresso extraction time for a double shot?","options":["20-30 seconds","5 seconds","60 seconds","2 minutes"],"answer":"20-30 seconds"}],"lessonId":"barista-common-l1"},{"id":"barista-common-l2-quiz","programId":"barista","title":"Workplace Safety & Emergency Procedures Quiz","passing":75,"timeLimit":8,"published":true,"questions":[{"id":"barista-common-l2-quiz-q1","type":"mcq","q":"The ideal microfoam texture is best described as:","options":["Glossy wet paint","Dry and stiff","Large bubbles","Watery"],"answer":"Glossy wet paint"},{"id":"barista-common-l2-quiz-q2","type":"tf","q":"Milk should be steamed to about 60-65°C for best taste.","answer":true},{"id":"barista-common-l2-quiz-q3","type":"id","q":"The free-pour pattern that looks like a leaf is called a ______.","answer":"rosetta"},{"id":"barista-common-l2-quiz-q4","type":"mcq","q":"Over-steaming milk results in:","options":["Burnt, flat taste","Sweet flavor","Better foam","Colder milk"],"answer":"Burnt, flat taste"}],"lessonId":"barista-common-l2"},{"id":"barista-common-l3-quiz","programId":"barista","title":"Customer Service Excellence Quiz","passing":75,"timeLimit":10,"published":true,"questions":[{"id":"barista-common-l3-quiz-q1","type":"mcq","q":"Which coffee species is generally considered higher quality?","options":["Arabica","Robusta","Liberica","Excelsa"],"answer":"Arabica"},{"id":"barista-common-l3-quiz-q2","type":"tf","q":"Finer grind is used for espresso than for French press.","answer":true},{"id":"barista-common-l3-quiz-q3","type":"id","q":"The process of heating milk with steam to create foam is called ______.","answer":"steaming"},{"id":"barista-common-l3-quiz-q4","type":"mcq","q":"A darker roast generally produces what flavor?","options":["Smoky and bitter","Fruity and bright","Floral and light","Sour"],"answer":"Smoky and bitter"},{"id":"barista-common-l3-quiz-q5","type":"tf","q":"Coffee beans should be stored in an airtight container away from light.","answer":true}],"lessonId":"barista-common-l3"},{"id":"barista-common-l4-quiz","programId":"barista","title":"Working with Others & Time Management Quiz","passing":75,"timeLimit":10,"published":true,"questions":[{"id":"barista-common-l4-quiz-q1","type":"mcq","q":"A standard single espresso shot is approximately how many ounces?","options":["1 oz","3 oz","5 oz","8 oz"],"answer":"1 oz"},{"id":"barista-common-l4-quiz-q2","type":"tf","q":"Under-extracted espresso tastes sour and thin.","answer":true},{"id":"barista-common-l4-quiz-q3","type":"id","q":"The tool used to level and press coffee grounds is called a ______.","answer":"tamper"},{"id":"barista-common-l4-quiz-q4","type":"mcq","q":"What is the ideal espresso extraction time for a double shot?","options":["20-30 seconds","5 seconds","60 seconds","2 minutes"],"answer":"20-30 seconds"}],"lessonId":"barista-common-l4"},{"id":"barista-core-u1-l1-quiz","programId":"barista","title":"Introduction to Coffee Quiz","passing":75,"timeLimit":8,"published":true,"questions":[{"id":"barista-core-u1-l1-quiz-q1","type":"mcq","q":"The ideal microfoam texture is best described a