insert into public.programs (id, code, title, trainer_id, data)
values ('hilot', 'HIL-306', 'Hilot (Wellness Massage) NC II', 'tr-003', $prog${"id":"hilot","code":"HIL-306","title":"Hilot (Wellness Massage) NC II","category":"Health & Wellness","level":"NC II","special":false,"enrollable":false,"description":"Learn traditional Filipino hilot and therapeutic massage techniques for wellness and spa establishments.","overview":"The Hilot (Wellness Massage) NC II program trains individuals in the art and science of Filipino hilot and therapeutic massage. It covers anatomy and physiology, massage techniques, full-body massage sequences, and professional client care and spa operations.","duration":"3 months","hours":150,"fee":9000,"color":"from-emerald-500 to-teal-600","image":"/courses/hilot.jpg","requirements":["At least 18 years old","High School graduate or ALS equivalent","Physically fit (medical certificate)","Negative skin test / health clearance","Birth certificate (PSA)","2 pcs. 2x2 ID picture"],"trainerId":"tr-003","competencies":[{"id":"hilot-basic","type":"Basic","title":"Basic Competency","description":"Foundational skills required of every trainee: communication, numeracy, digital literacy and workplace behavior.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"hilot-basic-l1","title":"Reading, Writing & Comprehension","description":"Develop the ability to read, interpret and write workplace documents, forms and simple reports.","duration":45,"video":"Introduction to Workplace Literacy","materials":[{"id":"hilot-basic-l1-m1","name":"Reading Comprehension Guide.pdf","type":"pdf","url":""},{"id":"hilot-basic-l1-m2","name":"Workplace Forms Template.docx","type":"doc","url":""}],"content":"This lesson builds the foundational literacy skills needed in a technical-vocational workplace. You will practice reading instructions, interpreting forms, and writing simple reports and messages clearly and accurately.","quizId":"hilot-basic-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"hilot-basic-l2","title":"Basic Communication Skills","description":"Learn verbal and non-verbal communication techniques for professional workplace interaction.","duration":40,"video":"Effective Workplace Communication","materials":[{"id":"hilot-basic-l2-m1","name":"Communication Etiquette Handout.pdf","type":"pdf","url":""}],"content":"Communication is the backbone of any workplace. This lesson covers active listening, professional tone, giving and receiving feedback, and adapting your communication style to different audiences.","quizId":"hilot-basic-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"hilot-basic-l3","title":"Basic Digital Literacy","description":"Familiarize yourself with computers, the internet, email and basic productivity tools.","duration":60,"video":"Getting Started with Computers","materials":[{"id":"hilot-basic-l3-m1","name":"Digital Skills Workbook.pdf","type":"pdf","url":""},{"id":"hilot-basic-l3-m2","name":"Keyboard Shortcuts Cheatsheet.pdf","type":"pdf","url":""}],"content":"Digital literacy is essential for modern employment. This lesson introduces operating systems, file management, internet browsing, email, and cloud-based productivity tools.","quizId":"hilot-basic-l3-quiz"},{"videoUrl":"","published":true,"order":4,"id":"hilot-basic-l4","title":"Workplace Behavior & Professionalism","description":"Understand workplace ethics, punctuality, grooming, and professional conduct.","duration":35,"video":"Professional Conduct at Work","materials":[{"id":"hilot-basic-l4-m1","name":"Code of Conduct.pdf","type":"pdf","url":""}],"content":"Professionalism covers punctuality, appropriate attire, respect for colleagues, following rules and regulations, and taking responsibility for your work.","quizId":"hilot-basic-l4-quiz"}]},{"id":"hilot-common","type":"Common","title":"Common Competency","description":"Skills common across technical-vocational industries: workplace communication, safety, customer service and teamwork.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"hilot-common-l1","title":"Workplace Communication","description":"Communicate effectively with clients, colleagues and supervisors using industry-appropriate language.","duration":50,"video":"Communicating in the Workplace","materials":[{"id":"hilot-common-l1-m1","name":"Communication Scenarios.pdf","type":"pdf","url":""}],"content":"This lesson focuses on industry-specific communication: handling inquiries, reporting incidents, participating in meetings, and documenting work activities.","quizId":"hilot-common-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"hilot-common-l2","title":"Workplace Safety & Emergency Procedures","description":"Identify hazards, follow OSH standards, and respond to workplace emergencies.","duration":55,"video":"Occupational Safety and Health","materials":[{"id":"hilot-common-l2-m1","name":"OSH Standards Manual.pdf","type":"pdf","url":""},{"id":"hilot-common-l2-m2","name":"Emergency Evacuation Plan.pdf","type":"pdf","url":""}],"content":"Occupational Safety and Health (OSH) is a legal requirement. Learn to identify hazards, use protective equipment, follow safety signage, and respond to emergencies such as fire, earthquake, and medical incidents.","quizId":"hilot-common-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"hilot-common-l3","title":"Customer Service Excellence","description":"Deliver quality service that meets and exceeds customer expectations.","duration":45,"video":"Service Quality Standards","materials":[{"id":"hilot-common-l3-m1","name":"Customer Service Standards.pdf","type":"pdf","url":""}],"content":"Excellent customer service builds loyalty and reputation. Learn the principles of service quality, handling complaints, and creating positive customer experiences.","quizId":"hilot-common-l3-quiz"},{"videoUrl":"","published":true,"order":4,"id":"hilot-common-l4","title":"Working with Others & Time Management","description":"Collaborate effectively in teams and manage your time and priorities.","duration":40,"video":"Teamwork and Productivity","materials":[{"id":"hilot-common-l4-m1","name":"Teamwork Activity Sheet.pdf","type":"pdf","url":""}],"content":"Success in the workplace depends on teamwork and personal productivity. This lesson covers collaboration, conflict resolution, prioritization, and effective scheduling.","quizId":"hilot-common-l4-quiz"}]},{"id":"hilot-core","type":"Core","title":"Core Competency","description":"Core competencies of Hilot NC II: anatomy and physiology, hilot techniques, full-body massage sequence, and client care.","lessons":[],"units":[{"id":"hilot-core-u1","title":"Anatomy & Physiology Fundamentals","description":"Understand the human body systems relevant to massage therapy.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"hilot-core-u1-l1","title":"Skeletal & Muscular System","description":"Identify major bones, muscles and joints of the human body.","duration":55,"video":"Skeletal & Muscular System","materials":[{"id":"hilot-core-u1-l1-m1","name":"Anatomy Charts.pdf","type":"pdf","url":""}],"content":"Learn the structure of the skeletal and muscular systems, muscle groups, and how they relate to massage techniques.","quizId":"hilot-core-u1-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"hilot-core-u1-l2","title":"Circulatory & Lymphatic Systems","description":"Understand circulation and lymph flow for therapeutic massage.","duration":45,"video":"Circulatory & Lymphatic Systems","materials":[{"id":"hilot-core-u1-l2-m1","name":"Circulatory System Notes.pdf","type":"pdf","url":""}],"content":"Understand how massage affects blood circulation and lymphatic drainage, and why direction of strokes matters.","quizId":"hilot-core-u1-l2-quiz"}]},{"id":"hilot-core-u2","title":"Hilot Techniques & Fundamentals","description":"Apply traditional Filipino hilot massage techniques.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"hilot-core-u2-l1","title":"Introduction to Hilot","description":"Understand the history and philosophy of Filipino hilot.","duration":45,"video":"Introduction to Hilot","materials":[{"id":"hilot-core-u2-l1-m1","name":"Hilot History & Ethics.pdf","type":"pdf","url":""}],"content":"Explore the traditional Filipino healing art of hilot, its cultural roots, and its modern therapeutic application.","quizId":"hilot-core-u2-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"hilot-core-u2-l2","title":"Basic Massage Strokes","description":"Perform effleurage, petrissage, tapotement and friction.","duration":60,"video":"Basic Massage Strokes","materials":[{"id":"hilot-core-u2-l2-m1","name":"Massage Strokes Guide.pdf","type":"pdf","url":""}],"content":"Learn the five fundamental massage strokes, correct hand placement, pressure application, and rhythm.","quizId":"hilot-core-u2-l2-quiz"}]},{"id":"hilot-core-u3","title":"Full Body Massage Sequence","description":"Perform a complete therapeutic full-body massage.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"hilot-core-u3-l1","title":"Back, Shoulder & Neck Massage","description":"Perform massage on the back, shoulders and neck.","duration":55,"video":"Back, Shoulder & Neck Massage","materials":[{"id":"hilot-core-u3-l1-m1","name":"Back Massage Sequence.pdf","type":"pdf","url":""}],"content":"Learn the sequence for the back, shoulders and neck including draping, pressure points and finishing strokes.","quizId":"hilot-core-u3-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"hilot-core-u3-l2","title":"Limb & Foot Massage","description":"Perform massage on arms, hands, legs and feet.","duration":50,"video":"Limb & Foot Massage","materials":[{"id":"hilot-core-u3-l2-m1","name":"Limb Massage Guide.pdf","type":"pdf","url":""}],"content":"Complete the full-body sequence with arm, hand, leg and foot massage, including reflexology basics.","quizId":"hilot-core-u3-l2-quiz"}]},{"id":"hilot-core-u4","title":"Client Care & Spa Operations","description":"Manage client consultation, hygiene and spa protocols.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"hilot-core-u4-l1","title":"Client Consultation & Contraindications","description":"Assess client needs and identify contraindications to massage.","duration":45,"video":"Client Consultation & Contraindications","materials":[{"id":"hilot-core-u4-l1-m1","name":"Client Intake Form.pdf","type":"pdf","url":""}],"content":"Learn intake consultation, contraindications, informed consent, and adapting treatments to client needs.","quizId":"hilot-core-u4-l1-quiz"}]}]}],"quizzes":[{"id":"hilot-basic-l1-quiz","programId":"hilot","title":"Reading, Writing & Comprehension Quiz","passing":75,"timeLimit":10,"published":true,"questions":[{"id":"hilot-basic-l1-quiz-q1","type":"mcq","q":"Which system carries blood throughout the body?","options":["Circulatory","Skeletal","Nervous","Digestive"],"answer":"Circulatory"},{"id":"hilot-basic-l1-quiz-q2","type":"tf","q":"Massage strokes generally follow the direction of blood flow toward the heart.","answer":true},{"id":"hilot-basic-l1-quiz-q3","type":"id","q":"The _____ system includes lymph nodes and vessels.","answer":"lymphatic"},{"id":"hilot-basic-l1-quiz-q4","type":"mcq","q":"The largest muscle group in the body is found in the:","options":["Back and legs","Fingers","Ears","Neck"],"answer":"Back and legs"},{"id":"hilot-basic-l1-quiz-q5","type":"tf","q":"Understanding anatomy helps a therapist avoid injury to clients.","answer":true}],"lessonId":"hilot-basic-l1"},{"id":"hilot-basic-l2-quiz","programId":"hilot","title":"Basic Communication Skills Quiz","passing":75,"timeLimit":10,"published":true,"questions":[{"id":"hilot-basic-l2-quiz-q1","type":"mcq","q":"A long, gliding stroke is called:","options":["Effleurage","Tapotement","Petrissage","Friction"],"answer":"Effleurage"},{"id":"hilot-basic-l2-quiz-q2","type":"tf","q":"Hilot is a traditional Filipino healing art.","answer":true},{"id":"hilot-basic-l2-quiz-q3","type":"id","q":"Kneading and squeezing techniques are called ______.","answer":"petrissage"},{"id":"hilot-basic-l2-quiz-q4","type":"mcq","q":"Which stroke uses rhythmic tapping?","options":["Tapotement","Effleurage","Friction","Petrissage"],"answer":"Tapotement"}],"lessonId":"hilot-basic-l2"},{"id":"hilot-basic-l3-quiz","programId":"hilot","title":"Basic Digital Literacy Quiz","passing":75,"timeLimit":8,"published":true,"questions":[{"id":"hilot-basic-l3-quiz-q1","type":"mcq","q":"A condition where massage should be avoided is called a:","options":["Contraindication","Prescription","Indication","Diagnosis"],"answer":"Contraindication"},{"id":"hilot-basic-l3-quiz-q2","type":"tf","q":"Informed consent should be obtained before any massage session.","answer":true},{"id":"hilot-basic-l3-quiz-q3","type":"id","q":"A ______ should always be completed before treatment begins.","answer":"consultation"},{"id":"hilot-basic-l3-quiz-q4","type":"mcq","q":"Massage should NOT be performed over:","options":["Open wounds","Muscles","Relaxed areas","Clean skin"],"answer":"Open wounds"}],"lessonId":"hilot-basic-l3"},{"id":"hilot-basic-l4-quiz","programId":"hilot","title":"Workplace Behavior & Professionalism Quiz","passing":75,"timeLimit":10,"published":true,"questions":[{"id":"hilot-basic-l4-quiz-q1","type":"mcq","q":"Which system carries blood throughout the body?","options":["Circulatory","Skeletal","Nervous","Digestive"],"answer":"Circulatory"},{"id":"hilot-basic-l4-quiz-q2","type":"tf","q":"Massage strokes generally follow the direction of blood flow toward the heart.","answer":true},{"id":"hilot-basic-l4-quiz-q3","type":"id","q":"The _____ system includes lymph nodes and vessels.","answer":"lymphatic"},{"id":"hilot-basic-l4-quiz-q4","type":"mcq","q":"The largest muscle group in the body is found in the:","options":["Back and legs","Fingers","Ears","Neck"],"answer":"Back and legs"},{"id":"hilot-basic-l4-quiz-q5","type":"tf","q":"Understanding anatomy helps a therapist avoid injury to clients.","answer":true}],"lessonId":"hilot-b