insert into public.programs (id, code, title, trainer_id, data)
values ('event-management', 'EVT-408', 'Event Management Services NC II', 'tr-004', $prog${"id":"event-management","code":"EVT-408","title":"Event Management Services NC II","category":"Tourism & Hospitality","level":"NC II","special":false,"enrollable":false,"description":"Plan, organize and execute events including budgeting, logistics, stage production and post-event evaluation.","overview":"The Event Management Services NC II program prepares trainees to plan and deliver successful events. It covers event conceptualization, budgeting, logistics and supplier coordination, event-day production, and post-event evaluation and reporting.","duration":"3 months","hours":140,"fee":8800,"color":"from-fuchsia-500 to-purple-600","image":"/courses/event-management.jpg","requirements":["At least 18 years old","High School graduate or ALS equivalent","Good communication skills","Birth certificate (PSA)","2 pcs. 2x2 ID picture","Barangay clearance"],"trainerId":"tr-004","competencies":[{"id":"event-management-basic","type":"Basic","title":"Basic Competency","description":"Foundational skills required of every trainee: communication, numeracy, digital literacy and workplace behavior.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"event-management-basic-l1","title":"Reading, Writing & Comprehension","description":"Develop the ability to read, interpret and write workplace documents, forms and simple reports.","duration":45,"video":"Introduction to Workplace Literacy","materials":[{"id":"event-management-basic-l1-m1","name":"Reading Comprehension Guide.pdf","type":"pdf","url":""},{"id":"event-management-basic-l1-m2","name":"Workplace Forms Template.docx","type":"doc","url":""}],"content":"This lesson builds the foundational literacy skills needed in a technical-vocational workplace. You will practice reading instructions, interpreting forms, and writing simple reports and messages clearly and accurately.","quizId":"event-management-basic-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"event-management-basic-l2","title":"Basic Communication Skills","description":"Learn verbal and non-verbal communication techniques for professional workplace interaction.","duration":40,"video":"Effective Workplace Communication","materials":[{"id":"event-management-basic-l2-m1","name":"Communication Etiquette Handout.pdf","type":"pdf","url":""}],"content":"Communication is the backbone of any workplace. This lesson covers active listening, professional tone, giving and receiving feedback, and adapting your communication style to different audiences.","quizId":"event-management-basic-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"event-management-basic-l3","title":"Basic Digital Literacy","description":"Familiarize yourself with computers, the internet, email and basic productivity tools.","duration":60,"video":"Getting Started with Computers","materials":[{"id":"event-management-basic-l3-m1","name":"Digital Skills Workbook.pdf","type":"pdf","url":""},{"id":"event-management-basic-l3-m2","name":"Keyboard Shortcuts Cheatsheet.pdf","type":"pdf","url":""}],"content":"Digital literacy is essential for modern employment. This lesson introduces operating systems, file management, internet browsing, email, and cloud-based productivity tools.","quizId":"event-management-basic-l3-quiz"},{"videoUrl":"","published":true,"order":4,"id":"event-management-basic-l4","title":"Workplace Behavior & Professionalism","description":"Understand workplace ethics, punctuality, grooming, and professional conduct.","duration":35,"video":"Professional Conduct at Work","materials":[{"id":"event-management-basic-l4-m1","name":"Code of Conduct.pdf","type":"pdf","url":""}],"content":"Professionalism covers punctuality, appropriate attire, respect for colleagues, following rules and regulations, and taking responsibility for your work.","quizId":"event-management-basic-l4-quiz"}]},{"id":"event-management-common","type":"Common","title":"Common Competency","description":"Skills common across technical-vocational industries: workplace communication, safety, customer service and teamwork.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"event-management-common-l1","title":"Workplace Communication","description":"Communicate effectively with clients, colleagues and supervisors using industry-appropriate language.","duration":50,"video":"Communicating in the Workplace","materials":[{"id":"event-management-common-l1-m1","name":"Communication Scenarios.pdf","type":"pdf","url":""}],"content":"This lesson focuses on industry-specific communication: handling inquiries, reporting incidents, participating in meetings, and documenting work activities.","quizId":"event-management-common-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"event-management-common-l2","title":"Workplace Safety & Emergency Procedures","description":"Identify hazards, follow OSH standards, and respond to workplace emergencies.","duration":55,"video":"Occupational Safety and Health","materials":[{"id":"event-management-common-l2-m1","name":"OSH Standards Manual.pdf","type":"pdf","url":""},{"id":"event-management-common-l2-m2","name":"Emergency Evacuation Plan.pdf","type":"pdf","url":""}],"content":"Occupational Safety and Health (OSH) is a legal requirement. Learn to identify hazards, use protective equipment, follow safety signage, and respond to emergencies such as fire, earthquake, and medical incidents.","quizId":"event-management-common-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"event-management-common-l3","title":"Customer Service Excellence","description":"Deliver quality service that meets and exceeds customer expectations.","duration":45,"video":"Service Quality Standards","materials":[{"id":"event-management-common-l3-m1","name":"Customer Service Standards.pdf","type":"pdf","url":""}],"content":"Excellent customer service builds loyalty and reputation. Learn the principles of service quality, handling complaints, and creating positive customer experiences.","quizId":"event-management-common-l3-quiz"},{"videoUrl":"","published":true,"order":4,"id":"event-management-common-l4","title":"Working with Others & Time Management","description":"Collaborate effectively in teams and manage your time and priorities.","duration":40,"video":"Teamwork and Productivity","materials":[{"id":"event-management-common-l4-m1","name":"Teamwork Activity Sheet.pdf","type":"pdf","url":""}],"content":"Success in the workplace depends on teamwork and personal productivity. This lesson covers collaboration, conflict resolution, prioritization, and effective scheduling.","quizId":"event-management-common-l4-quiz"}]},{"id":"event-management-core","type":"Core","title":"Core Competency","description":"Core competencies of Event Management NC II: event planning, budgeting and logistics, event execution and production, and post-event evaluation.","lessons":[],"units":[{"id":"event-management-core-u1","title":"Event Planning Fundamentals","description":"Plan events from concept to execution.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"event-management-core-u1-l1","title":"Introduction to Event Management","description":"Understand the event industry, types of events and roles.","duration":45,"video":"Introduction to Event Management","materials":[{"id":"event-management-core-u1-l1-m1","name":"Event Industry Overview.pdf","type":"pdf","url":""}],"content":"Learn about corporate, social, and MICE events, and the roles within an event team from planner to coordinator.","quizId":"event-management-core-u1-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"event-management-core-u1-l2","title":"Event Conceptualization & Theming","description":"Develop event concepts, themes and objectives.","duration":50,"video":"Event Conceptualization & Theming","materials":[{"id":"event-management-core-u1-l2-m1","name":"Concept Development Worksheet.pdf","type":"pdf","url":""}],"content":"Translate client goals into a cohesive event concept, including theme, mood board, and creative direction.","quizId":"event-management-core-u1-l2-quiz"}]},{"id":"event-management-core-u2","title":"Budgeting & Logistics","description":"Prepare event budgets and coordinate logistics.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"event-management-core-u2-l1","title":"Event Budgeting","description":"Create and manage an event budget and cost sheet.","duration":50,"video":"Event Budgeting","materials":[{"id":"event-management-core-u2-l1-m1","name":"Event Budget Template.xlsx","type":"xls","url":""}],"content":"Learn to build a line-item budget, estimate costs, negotiate with suppliers, and track expenses.","quizId":"event-management-core-u2-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"event-management-core-u2-l2","title":"Venue & Supplier Coordination","description":"Select venues and coordinate with suppliers and vendors.","duration":45,"video":"Venue & Supplier Coordination","materials":[{"id":"event-management-core-u2-l2-m1","name":"Supplier Checklist.pdf","type":"pdf","url":""}],"content":"Evaluate venue capacity, layout and accessibility; coordinate catering, AV, decor and other suppliers.","quizId":"event-management-core-u2-l2-quiz"}]},{"id":"event-management-core-u3","title":"Event Execution & Production","description":"Run event day operations and stage production.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"event-management-core-u3-l1","title":"Program Flow & Stage Management","description":"Create program flow and manage stage production.","duration":55,"video":"Program Flow & Stage Management","materials":[{"id":"event-management-core-u3-l1-m1","name":"Program Flow Template.pdf","type":"pdf","url":""}],"content":"Build a minute-by-minute program flow, manage cues, and coordinate backstage with the technical team.","quizId":"event-management-core-u3-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"event-management-core-u3-l2","title":"Event Day Operations","description":"Manage registration, ushering and on-site coordination.","duration":50,"video":"Event Day Operations","materials":[{"id":"event-management-core-u3-l2-m1","name":"Event Day Run Sheet.pdf","type":"pdf","url":""}],"content":"Handle registration, guest management, ushering, and contingency planning during the event.","quizId":"event-management-core-u3-l2-quiz"}]},{"id":"event-management-core-u4","title":"Post-Event Evaluation","description":"Evaluate events and prepare post-event reports.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"event-management-core-u4-l1","title":"Post-Event Reporting","description":"Prepare post-event reports and client debriefs.","duration":40,"video":"Post-Event Reporting","materials":[{"id":"event-management-core-u4-l1-m1","name":"Post-Event Report Template.pdf","type":"pdf","url":""}],"content":"Compile attendance, financials and feedback into a post-event report, and conduct a client debrief.","quizId":"event-management-core-u4-l1-quiz"}]}]}],"quizzes":[{"id":"event-management-basic-l1-quiz","programId":"event-management","title":"Reading, Writing & Comprehension Quiz","passing":75,"timeLimit":10,"published":true,"questions":[{"id":"event-management-basic-l1-quiz-q1","type":"mcq","q":"MICE stands for Meetings, Incentives, Conferences and:","options":["Exhibitions","Events","Entertainment","Excursions"],"answer":"Exhibitions"},{"id":"event-management-basic-l1-quiz-q2","type":"tf","q":"A theme should align with the client’s objectives.","answer":true},{"id":"event-management-basic-l1-quiz-q3","type":"id","q":"A ______ is used to present the visual direction of an event.","answer":"moodboard"},{"id":"event-management-basic-l1-quiz-q4","type":"mcq","q":"The first stage of event planning is:","options":["Conceptualization","Execution","Evaluation","Billing"],"answer":"Conceptualization"},{"id":"event-management-basic-l1-quiz-q5","type":"tf","q":"Event planning should always start with a clear objective.","answer":true}],"lessonId":"event-management-basic-l1"},{"id":"event-management-basic-l2-quiz","programId":"event-management","title":"Basic Communication Skills Quiz","passing":75,"timeLimit":10,"published":true,"questions":[{"id":"event-management-basic-l2-quiz-q1","type":"mcq","q":"A contingency fund in an event budget covers:","options":["Unexpected costs","Staff salaries only","Decorations","Invitations"],"answer":"Unexpected costs"},{"id":"event-management-basic-l2-quiz-q2","type":"tf","q":"Venue capacity should match the expected number of guests.","answer":true},{"id":"event-management-basic-l2-quiz-q3","type":"id","q":"The person responsible for the overall event is the event ______.","answer":"planner"},{"id":"event-management-basic-l2-quiz-q4","type":"mcq","q":"Which document lists every expense of an event?","options":["Budget","Guest list","Menu","Floor plan"],"answer":"Budget"}],"lessonId":"event-management-basic-l2"},{"id":"event-management-basic-l3-quiz","programId":"event-management","title":"Basic Digital Literacy Quiz","passing":75,"timeLimit":8,"published":true,"questions":[{"id":"event-management-basic-l3-quiz-q1","type":"mcq","q":"A minute-by-minute schedule of an event is called:","options":["Run sheet","Menu","Contract","Invoice"],"answer":"Run sheet"},{"id":"event-management-basic-l3-quiz-q2","type":"tf","q":"Backstage coordination is handled by stage management.","answer":true},{"id":"event-management-basic-l3-quiz-q3","type":"id","q":"Managing guest arrival and check-in is called ______.","answer":"registration"},{"id":"event-management-basic-l3-quiz-q4","type":"mcq","q":"A post-event report typically includes:","options":["Attendance and financials","Only photos","Guest complaints only","The menu"],"answer":"Attendance and financials"}],"lessonId":"event-management-basic-l3"},{"id":"event-management-basic-l4-quiz","programId":"event-management","title":"Workplace Behavior & Professionalism Quiz","passing":75,"timeLimit